preConditionHook:
// CONFLUENCE (G16-20): the support level of a RECENT window sits within tolAtr
// ATRs of the support level of an OLDER, LONGER one -- levels from two scales
// lining up at one price. Mirrored on the highs.
//
// THE WINDOWS MUST NOT OVERLAP: a nested long window's low is at or below the
// short window's and the test would fire trivially. The recent window is bars
// 1..shortLookback and the older one bars shortLookback+1 ..
// shortLookback+longLookback -- ReversalShortOfPriorExtreme's construction,
// with the offset on the price series.
//
// Both levels are one-bar-shifted window extremes (merge decision 7) and the
// tolerance is an ATR fraction, never ticks. EL's Extremes() -- which
// Highest()/Lowest() call -- seeds at the FIRST element of the window (the
// nearest bar) and scans elements 1..Length-1 with a strict,
// tolerance-carrying comparison, so each loop below seeds at its window's
// nearest bar and scans the remainder.
//
// WFSafe_AvgTrueRange is MultiWalk's rolling accumulator, re-seeded on a length
// change and updated as TWO statements; AtrProfitTarget carries the notes.
//
// oBase is a local rather than a hook-scope const: a rule can be placed twice
// in one strategy and its hooks are emitted twice into one class.
//
// Deepest bar touched: max(shortLookback + longLookback, atrLength + 1).
recentLow = low[1];
recentHigh = high[1];
for (int i = 2; i <= (int)shortLookback; ++i) {
    if (el_lt(low[i], recentLow)) recentLow = low[i];
    if (el_gt(high[i], recentHigh)) recentHigh = high[i];
}
oBase = (int)shortLookback + 1;
olderLow = low[oBase];
olderHigh = high[oBase];
for (int i = 1; i < (int)longLookback; ++i) {
    if (el_lt(low[oBase + i], olderLow)) olderLow = low[oBase + i];
    if (el_gt(high[oBase + i], olderHigh)) olderHigh = high[oBase + i];
}
if (atrLen != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLength;
tol = tolAtr * atr;
